cypress_script:
describe('Dropdown selection functionality', () => {
  it('should select Option 1 from the dropdown', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('Option 1');
    cy.get('#dropdown').should('have.value', '1');
  });

  it('should not change the URL when no option is selected', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/dropdown');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Dropdown selection functionality', () => {
  test('should select Option 1 from the dropdown', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', '1');
    const value = await page.locator('#dropdown').inputValue();
    expect(value).toBe('1');
  });

  test('should not change the URL when no option is selected', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
    await page.selectOption('#dropdown', '');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/dropdown');
  });
});
